mapper.select:
SELECT * FROM ( SELECT ROW_NUMBER() OVER ( ORDER BY TOP_FIX_YN DESC , REG_DTTM DESC ) RN , ANN_NO , BOARD_NO , TTL , CN , WRTR_ID , REG_DTTM , MDF_DTTM , INQ_CNT , DEL_YN , ATCH_FILE_ID , TOP_FIX_YN FROM APT_ANN_BOARD_POST WHERE DEL_YN = 'N'
AND TTL LIKE '%' || #{searchTtl} || '%'
) WHERE RN BETWEEN #{startRow} AND #{endRow}

mapper.insert:
        INSERT INTO APT_ANN_BOARD_POST
        (
          ANN_NO
        , BOARD_NO
        , TTL
        , CN
        , WRTR_ID
        , TOP_FIX_YN
        , REG_DTTM
        , DEL_YN
        )
        VALUES
            (
              'ANN' || LPAD(SEQ_APT_ANN_BOARD_POST.NEXTVAL, 8, '0')
            , #{boardNo}
            , #{ttl}
            , #{cn}
            , #{wrtrId}
            , #{topFixYn}
            , SYSDATE
            , 'N'
            )

mapper.update:
        UPDATE APT_ANN_BOARD_POST
        SET TTL = #{ttl}
          , CN = #{cn}
          , TOP_FIX_YN = #{topFixYn}
          , MDF_DTTM = SYSDATE
        WHERE ANN_NO = #{annNo}

        UPDATE APT_ANN_BOARD_POST
        SET DEL_YN = 'Y'
        WHERE ANN_NO = #{annNo}

mapper.select:
/* ImngrRegidentNoticeMapper.selectAptCmplexNoByMgmtOfcNo */
SELECT apt_cmplex_no
FROM mgmt_office
WHERE mgmt_ofc_no = #{mgmtOfcNo}
  AND use_yn = 'Y'

/* ImngrRegidentNoticeMapper.selectNoticeBoardNoByAptCmplexNo */
SELECT board_no
FROM apt_board_instance
WHERE apt_cmplex_no = #{aptCmplexNo}
  AND board_ty_cd = 'NOTICE'
  AND use_yn = 'Y'
